package com.collabboard.websocket;
import com.collabboard.security.AuthPrincipal;import com.collabboard.service.RoomService;import org.springframework.context.event.EventListener;import org.springframework.messaging.simp.SimpMessagingTemplate;import org.springframework.messaging.simp.stomp.StompHeaderAccessor;import org.springframework.stereotype.Component;import org.springframework.web.socket.messaging.SessionDisconnectEvent;import java.util.*;import java.util.concurrent.*;
@Component public class PresenceTracker {private final RoomService rooms;private final SimpMessagingTemplate messaging;private final Map<String,Map<String,AuthPrincipal>> roomSessions=new ConcurrentHashMap<>();private final Map<String,String> sessionRooms=new ConcurrentHashMap<>();public PresenceTracker(RoomService r,SimpMessagingTemplate m){rooms=r;messaging=m;}public void join(String room,String session,AuthPrincipal p){roomSessions.computeIfAbsent(room,k->new ConcurrentHashMap<>()).put(session,p);sessionRooms.put(session,room);}public void leave(String session){String room=sessionRooms.remove(session);if(room==null)return;Map<String,AuthPrincipal> set=roomSessions.get(room);if(set!=null){set.remove(session);if(set.isEmpty())roomSessions.remove(room);broadcast(room);}}public void broadcast(String room){try{var board=rooms.getForPresence(room);var state=new HashMap<String,Object>();state.put("type","STATE");state.put("roomId",room);state.put("elements",board.elements());state.put("title",board.title());state.put("version",board.version());state.put("participants",roomSessions.getOrDefault(room,Map.of()).values().stream().map(AuthPrincipal::displayName).distinct().toList());for(String uid:rooms.authorizedUserIds(room))messaging.convertAndSendToUser(uid,"/queue/rooms/"+room,state);}catch(RuntimeException ignored){}}@EventListener public void disconnected(SessionDisconnectEvent event){leave(StompHeaderAccessor.wrap(event.getMessage()).getSessionId());}}
